{"sql": "CREATE OR REPLACE FUNCTION employees.generate_monthly_report(report_date DATE)
RETURNS INTEGER AS $$
DECLARE
    v_report_id INTEGER;
    v_department_count INTEGER;
    v_total_employees INTEGER;
    v_avg_salary DECIMAL(10, 2);
BEGIN
    -- Get department count
    SELECT COUNT(*) INTO v_department_count
    FROM employees.department;

    -- Get total active employees
    SELECT COUNT(*) INTO v_total_employees
    FROM employees.employee e
    JOIN employees.department_employee de ON e.id = de.employee_id
    WHERE de.to_date = '9999-01-01';

    -- Get average salary
    SELECT ROUND(AVG(s.amount), 2) INTO v_avg_salary
    FROM employees.employee e
    JOIN employees.salary s ON e.id = s.employee_id
    JOIN employees.department_employee de ON e.id = de.employee_id
    WHERE s.to_date = '9999-01-01' AND de.to_date = '9999-01-01';

    -- Insert the report
    INSERT INTO employees.monthly_reports (report_date, department_count, total_employees, avg_salary)
    VALUES (report_date, v_department_count, v_total_employees, v_avg_salary)
    RETURNING report_id INTO v_report_id;

    RETURN v_report_id;
END;
$$ LANGUAGE plpgsql;"}

{"sql": "CREATE OR REPLACE FUNCTION employees.high_salary_alert_trigger()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.amount > 120000 THEN
        INSERT INTO employees.salary_alerts (employee_id, salary_amount)
        VALUES (NEW.employee_id, NEW.amount);
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;"}
